"""Seal fixed full-routing comparison and original evidence before learning."""
from pathlib import Path
from flybrain_drive.evidence import write_json
from flybrain_drive.graph import sha256
from flybrain_drive.sac_unified_student import read

def main():
 root=Path('runs/fixed-full-routing-learning-20261104');root.mkdir(exist_ok=False);prior=read('runs/full-range-port-learning-20261104/source-receipt-final-01.json');old=dict(prior['preserved_production_and_checkpoint_sha256']);old.update(prior['current_checkpoints_sha256']);sources=dict(prior['preserved_prior_experiment_source_sha256']);sources.update({p:h for p,h in prior['source_and_documents_sha256'].items() if p.startswith(('src/','scripts/','tests/'))});assert all(sha256(p)==h for p,h in old.items());assert all(sha256(p)==h for p,h in sources.items());write_json(root/'initial-preservation-01.json',dict(source_revision=prior['source_revision'],preserved_production_and_checkpoint_sha256=old,preserved_prior_experiment_source_sha256=sources))
 p=read('runs/full-routing-initialization-20261104/plan-01.json');p.update(seed=781433,gate_learning_rate=0.,initialization_root='runs/full-routing-initialization-20261104',reserved_plan='runs/full-range-port-learning-20261104/next-reserved-plan-01.json',reserved_seed=915320137,source_sha256={f:sha256(f) for f in ['scripts/fixed_full_routing_experiment.py','scripts/fit_fixed_full_routing.py','scripts/evaluate_fixed_full_routing.py','scripts/validate_fixed_full_routing.py','scripts/prepare_fixed_full_routing.py']},scope='Gate frozen exactly 1, no gate parameter in optimizer. Matched visual-only/visual+native full-range inputs; measured chemical flight graph and signed muscle decoder fixed. Same continuous TRAIN/physical/image/synthetic schedule as prior. No native update from retimed/synthetic fixtures. Original fine comparison primary, warm signed affine is not an adequate quality baseline.')
 p['reserved_plan_sha256']=sha256(p['reserved_plan']);p['initialization_result_sha256']={str(Path(p['initialization_root'])/f'initial-episode{i}-01/result.json').replace(chr(92),'/'):sha256(Path(p['initialization_root'])/f'initial-episode{i}-01/result.json') for i in [0,1]};assert all(read(f)['yaw_both_correct']==read(f)['speed_both_correct']==15 for f in p['initialization_result_sha256']);write_json(root/'plan-01.json',p);print(len(old),len(sources))
if __name__=='__main__':main()
